          "explanation": "<b>顔に出る（かおにでる）：</b>Lộ rõ ra mặt, thể hiện cảm xúc lộ liễu trên sắc mặt.<br><b>Dịch nghĩa:</b> Cảm xúc của cô ấy thể hiện hết ra nét mặt nên rất dễ nhận biết.<br><i>Phân tích các phương án:</i><br>• <b>1. 顔: [Đúng] 気持ちが顔に出る (cảm xúc lộ rõ lên nét mặt)</b><br>• 2. 気: 気に入る (yêu thích), 気がつく (nhận ra)<br>• 3. 頭: 頭にくる (tức giận sôi máu)<br>• 4. 口: 口に出す (nói ra bằng lời)"
